const L3_RULES = [
 ['eb800','VP001'],['bm600','VP002'],['qm600','VP002'],
 ['elfa turbo pro','VP022'],['elfa turbo','VP016'],['elfa master limited','VP010'],['elfa master','VP009'],
 ['tappo eol','VP008'],['tappo','VP005'],['elfa new 1. july','VP004'],['elfa limited','VP006'],
 ['elfa refillable pod','VP011'],['elfa pod','VP003'],['elfa basisgerät','VP003'],['elfa','VP003'],
 ['elfx mega 10ml','VP020'],['elfx mega 5ml','VP021'],['elfx mega','VP025'],['elfx pro','VP018'],['elfx mini','VP023'],['elfx 2','VP024'],['elfx v2.0','VP012'],['elfx','VP017'],
 ['elfliq','VP013'],['elfbar max','VP015']
];
S.vapeProducts = VAPE_PRODUCTS.map(p=>({...p}));
S.vapeQuotes=S.vapeQuotes||[]; S.vapeInvoices=S.vapeInvoices||[];
S.vapeQuoteSequence=S.vapeQuoteSequence||0; S.vapeInvoiceSequence=S.vapeInvoiceSequence||0;
S.vapeMarkup=Math.min(25,Math.max(15,Number(S.vapeMarkup)||25));
S.vapePrivatePrices=S.vapePrivatePrices||{};
function privateEk(p){const key=matchL3Key(p);const ek=key?Number(S.vapePrivatePrices?.[key]):NaN;return Number.isFinite(ek)&&ek>=0?ek:null}
function matchL3Key(p){const x=((p?.name||'')+' '+(p?.variant||'')).toLowerCase().replace(/\s+/g,' ');for(const [needle,key] of L3_RULES)if(x.includes(needle))return key;return null}
function vapePrice(p){const ek=privateEk(p);return ek!==null?Math.round(ek*(1+S.vapeMarkup/100)*100)/100:null}
function cartCount(){return S.vapeCart.reduce((n,x)=>n+(+x.qty||0),0)}
function addToVapeCart(productId,qty=1){const p=S.vapeProducts.find(x=>x.id===productId),price=vapePrice(p);if(!p||price===null)return toast("Kein VK verfügbar – L3-Zuordnung prüfen");const q=Math.max(1,+qty||1),item=S.vapeCart.find(x=>x.productId===productId);if(item){item.qty+=q;item.price=price}else S.vapeCart.push({productId:p.id,name:p.name,variant:p.variant||"",qty:q,price});save();renderVape();toast(`${q} × ${p.name} im Warenkorb`)}
function updateVapeCart(productId,delta){const item=S.vapeCart.find(x=>x.productId===productId);if(!item)return;item.qty+=delta;if(item.qty<=0)S.vapeCart=S.vapeCart.filter(x=>x.productId!==productId);save();renderVape()}
function clearVapeCart(){S.vapeCart=[];save();renderVape();toast("Warenkorb geleert")}
function cartItems(){return S.vapeCart.map(x=>({productId:x.productId,description:x.name,variant:x.variant,qty:x.qty,unit:"Stück",price:x.price,ek:privateEk(S.vapeProducts.find(p=>p.id===x.productId))})).filter(x=>x.qty>0&&x.price>0)}
function openVapeCartQuote(){if(!cartItems().length)return toast("Warenkorb ist leer");newVapeQuoteFromCart()}
function newVapeQuoteFromCart(){S._quoteFromCart=true;newVapeQuote(null,null,null,cartItems())}
function vapeMargin(p){const ek=privateEk(p),vk=vapePrice(p);return ek!==null&&vk?1-ek/vk:null}
function setVapeMarkup(v){S.vapeMarkup=Math.min(25,Math.max(15,Number(v)||25));S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();}
function vapeProductOptions(){return '<option value="">Artikel wählen …</option>'+S.vapeProducts.map(p=>{const vk=vapePrice(p);return `<option value="${p.id}">${esc(p.name)} · ${vk===null?'VK —':`VK ${money(vk)}`}</option>`}).join('')}
function exportPrivateL3(){const payload={version:2,source:'L3-Preisliste des Nutzers',prices:S.vapePrivatePrices};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexaro-private-l3-prices.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importPrivateL3(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||typeof d.prices!=='object')throw 0;S.vapePrivatePrices={...d.prices};S.vapeCart=S.vapeCart.map(x=>{const p=S.vapeProducts.find(y=>y.id===x.productId),price=vapePrice(p);return price===null?x:{...x,price}});save();renderVape();toast(`${Object.keys(S.vapePrivatePrices).length} L3-Preise importiert`)}catch{toast('L3-Datei konnte nicht gelesen werden')}};r.readAsText(file)}
function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cell+='"';i++}else q=!q}else if((ch===','||ch===';')&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&nx==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function importDealerCSV(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const rows=parseCSV(String(r.result).replace(/^\uFEFF/,''));const head=rows.shift().map(x=>x.trim().replace(/^="(.*)"$/,'$1'));const ix=Object.fromEntries(head.map((h,i)=>[h,i]));const raw=rows.map((r,i)=>({Bestellnummer:(r[ix.Bestellnummer]||'').replace(/^="(.*)"$/,'$1'),Menge:(r[ix.Menge]||'').replace(/^="(.*)"$/,'$1'),EAN:(r[ix.EAN]||'').replace(/^="(.*)"$/,'$1'),Name:(r[ix.Name]||'').replace(/^="(.*)"$/,'$1'),Variante:(r[ix.Variante]||'').replace(/^="(.*)"$/,'$1')}));const n=raw.map(x=>x.Name.toLowerCase()),a=n.map(x=>x.includes('elfbar')),b=n.map((x,i)=>x.includes('einweg')&&!a[i]),c=n.map((x,i)=>x.includes('pod')&&!a[i]&&!x.includes('einweg')&&!x.includes('salt')&&!x.includes('liquid'));const keep=raw.filter((_,i)=>a[i]||b[i]||c[i]);S.vapeProducts=keep.map((x,i)=>({id:'CAT'+String(i+1).padStart(5,'0'),name:x.Name,variant:x.Variante,category:a[raw.indexOf(x)]?'ELFBAR':b[raw.indexOf(x)]?'Einweg':'Pods',orderNo:x.Bestellnummer,ean:x.EAN,qty:x.Menge}));save();renderVape();toast(`${S.vapeProducts.length} Vape-Artikel importiert`)}catch{toast('CSV konnte nicht gelesen werden')}};r.readAsText(file,'utf-8')}
function renderVape(){const q=($('#vapeSearch')?.value||'').toLowerCase();const ps=S.vapeProducts.filter(p=>[p.name,p.variant,p.category,p.id,p.orderNo,p.ean].join(' ').toLowerCase().includes(q));$('#vapeProductCount').textContent=S.vapeProducts.length;$('#vapeLeadCount').textContent=S.leads.length;$('#vapeQuoteCount').textContent=S.vapeQuotes.length;$('#vapeInvoiceCount').textContent=S.vapeInvoices.length;if($('#vapeMarkup'))$('#vapeMarkup').value=S.vapeMarkup;if($('#vapeMarkupValue'))$('#vapeMarkupValue').textContent=`${S.vapeMarkup}%`;const mapped=S.vapeProducts.filter(p=>privateEk(p)).length;if($('#vapeL3Status'))$('#vapeL3Status').textContent=Object.keys(S.vapePrivatePrices).length?`${Object.keys(S.vapePrivatePrices).length} L3-Werte geladen · ${mapped} Katalogartikel erkannt`:'Noch keine private L3-Datei geladen';const cart=cartItems(),cartNet=cart.reduce((a,x)=>a+x.qty*x.price,0);if($('#vapeCartBadge'))$('#vapeCartBadge').textContent=String(cartCount());if($('#vapeCart'))$('#vapeCart').innerHTML=cart.length?`<div class="row"><div><b>${cartCount()} Artikel</b><div class="meta">Warenwert netto ${money(cartNet)}</div></div><button class="secondary" data-cart-clear>🗑️ Leeren</button></div>${cart.map(x=>`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><div><b>${esc(x.description)}</b><div class="meta">${esc(x.variant||'')} · ${money(x.price)} / Stück</div></div><div class="row compact"><button class="secondary" data-cart-minus="${esc(x.productId)}">−</button><b>${x.qty}</b><button class="secondary" data-cart-plus="${esc(x.productId)}">＋</button></div></div>`).join('')}<div class="row" style="margin-top:12px"><b>Netto</b><b>${money(cartNet)}</b></div>`:'<div class="empty">Warenkorb ist leer. Füge Produkte aus dem Katalog hinzu.</div>';$('#vapeProductList').innerHTML=ps.map(p=>{const ek=privateEk(p),vk=vapePrice(p);return `<article class="card"><div class="row"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.variant||'')} · ${esc(p.category)} · ${esc(p.id)}</div></div><span class="badge">+ ${S.vapeMarkup}% EK</span></div><div class="chips"><span class="chip">RRP —</span>${ek!==null?`<span class="chip">EK L3 🔒 ${money(ek)}</span>`:'<span class="chip">EK L3 🔒 —</span>'}<span class="chip good">${vk===null?'VK —':`VK ${money(vk)}`}</span>${ek!==null?`<span class="chip">intern. Aufschlag ${S.vapeMarkup}%</span>`:'<span class="chip">L3-Zuordnung prüfen</span>'}</div><div class="lead-actions"><button ${vk===null?'disabled':''} data-vape-cart="${p.id}">🛒 In Warenkorb</button><button ${vk===null?'disabled':''} data-vape-add="${p.id}">＋ Einzel-Angebot</button></div></article>`}).join('')||'<div class="empty">Keine Artikel gefunden.</div>';$('#vapeQuoteList').innerHTML=S.vapeQuotes.map(q=>`<article class="card"><div class="row"><div><h3>${esc(q.number)} · ${esc(q.company)}</h3><div class="meta">${esc(q.date||'')} · ${esc(q.status||'Entwurf')}</div></div><b>${money(q.gross)}</b></div><div class="lead-actions"><button data-vq-edit="${q.id}">✏️ Bearbeiten</button><button data-vq-print="${q.id}">🖨️ Drucken / PDF</button><button data-vq-invoice="${q.id}">🧾 Rechnung</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Angebote.</div>';$('#vapeInvoiceList').innerHTML=S.vapeInvoices.map(i=>`<article class="card"><div class="row"><div><h3>${esc(i.number)} · ${esc(i.company)}</h3><div class="meta">${esc(i.date||'')} · fällig ${esc(i.due||'')}</div></div><b>${money(i.gross)}</b></div><div class="lead-actions"><button data-vi-edit="${i.id}">✏️ Bearbeiten</button><button data-vi-print="${i.id}">🖨️ Drucken / PDF</button></div></article>`).join('')||'<div class="empty">Noch keine Vape-Rechnungen.</div>'}
$('#vapeSearch')?.addEventListener('input',renderVape);
function newVapeLine(container,item={}){const wrap=document.createElement('div');wrap.className='line-item vape-line';wrap.innerHTML=`<select class="vape-item-product">${vapeProductOptions()}</select><input class="vape-item-qty" type="number" min="0.01" step="1" value="${item.qty||1}"><input class="vape-item-price" type="number" min="0" step="0.01" value="${item.price??''}"><button type="button" class="icon-btn vape-remove">✕</button>`;container.appendChild(wrap);if(item.productId)wrap.querySelector('.vape-item-product').value=item.productId;const sel=wrap.querySelector('.vape-item-product'),price=wrap.querySelector('.vape-item-price');if(item.price==null&&item.productId){const p=S.vapeProducts.find(x=>x.id===item.productId);price.value=vapePrice(p)??''}sel.onchange=()=>{const p=S.vapeProducts.find(x=>x.id===sel.value);price.value=vapePrice(p)??''};wrap.querySelector('.vape-remove').onclick=()=>{wrap.remove();renderVapeTotals()};wrap.querySelectorAll('input').forEach(x=>x.oninput=renderVapeTotals);return wrap}
function getVapeItems(container){return [...container.querySelectorAll('.line-item')].map(r=>{const p=S.vapeProducts.find(x=>x.id===r.querySelector('.vape-item-product').value);return {productId:p?.id||'',description:p?.name||'',variant:p?.variant||'',qty:+r.querySelector('.vape-item-qty').value||0,unit:'Stück',price:+r.querySelector('.vape-item-price').value||0,ek:privateEk(p)}}).filter(x=>x.description&&x.qty>0&&x.price>0)}
function totals(items){const net=items.reduce((a,x)=>a+x.qty*x.price,0);return{net,vat:net*.19,gross:net*1.19}}
function renderVapeTotals(){const a=totals(getVapeItems($('#vapeQuoteItems'))),b=totals(getVapeItems($('#vapeInvoiceItems')));if($('#vqNetPreview')){$('#vqNetPreview').textContent=money(a.net);$('#vqVatPreview').textContent=money(a.vat);$('#vqGrossPreview').textContent=money(a.gross)}if($('#viNetPreview')){$('#viNetPreview').textContent=money(b.net);$('#viVatPreview').textContent=money(b.vat);$('#viGrossPreview').textContent=money(b.gross)}}
function fillLeadSelect(id){$('#'+id).innerHTML='<option value="">Ohne Lead</option>'+S.leads.map(l=>`<option value="${l.id}">${esc(l.company)}</option>`).join('')}
function customerOptions(selected=""){return '<option value="">Kunden auswählen …</option>'+S.leads.map(l=>`<option value="${l.id}" ${l.id===selected?'selected':''}>${esc(l.company)}${l.contact?' · '+esc(l.contact):''}</option>`).join('')}
function fillVapeCustomer(selectId,companyId,contactId,emailId,vatId,customerNoId){const sel=$(selectId),l=S.leads.find(x=>x.id===sel?.value);if(l){$(companyId).value=l.company||'';$(contactId).value=l.contact||'';$(emailId).value=l.email||'';$(vatId).value=l.vatId||'';$(customerNoId).value=l.customerNo||''}}
function newVapeQuote(productId=null,leadId=null,existing=null,cart=null){$('#vapeQuoteForm').reset();$('#vqId').value=existing?.id||'';fillLeadSelect('vqLead');$('#vqCustomer').innerHTML=customerOptions(existing?.leadId||leadId||'');$('#vqCustomer').value=existing?.leadId||leadId||'';$('#vqDate').value=existing?.date||today();$('#vqCompany').value=existing?.company||'';$('#vqCustomerNo').value=existing?.customerNo||'';$('#vqContact').value=existing?.contact||'';$('#vqEmail').value=existing?.email||'';$('#vqVatId').value=existing?.vatId||'';$('#vqNote').value=existing?.note||'';$('#vapeQuoteItems').innerHTML='';(existing?.items||cart||[]).forEach(i=>newVapeLine($('#vapeQuoteItems'),i));if(!existing?.items?.length&&!cart?.length)newVapeLine($('#vapeQuoteItems'),productId?{productId,qty:1,price:vapePrice(S.vapeProducts.find(p=>p.id===productId))}:{});if(leadId){$('#vqLead').value=leadId;$('#vqLead').dispatchEvent(new Event('change'))}if(existing)$('#vqLead').value=existing.leadId||'';renderVapeTotals();open('vapeQuoteDialog')}
$('#vqLead')?.addEventListener('change',()=>{const l=S.leads.find(x=>x.id===$('#vqLead').value);if(l){$('#vqCustomer').value=l.id;$('#vqCompany').value=l.company;$('#vqCustomerNo').value=l.customerNo||'';$('#vqContact').value=l.contact||'';$('#vqEmail').value=l.email||'';$('#vqVatId').value=l.vatId||''}});$('#vqCustomer')?.addEventListener('change',()=>{const id=$('#vqCustomer').value;if(id){$('#vqLead').value=id;fillVapeCustomer('#vqCustomer','#vqCompany','#vqContact','#vqEmail','#vqVatId','#vqCustomerNo')}});$('#addVapeQuoteItem')?.addEventListener('click',()=>{newVapeLine($('#vapeQuoteItems'));renderVapeTotals()});const saveVapeQuote=()=>{const company=$('#vqCompany').value.trim(),items=getVapeItems($('#vapeQuoteItems')),t=totals(items);if(!company)return toast('Bitte Firma/Kunde eintragen');if(!items.length)return toast('Mindestens einen Artikel mit VK auswählen');const id=$('#vqId').value||uid(),old=S.vapeQuotes.find(x=>x.id===id),number=old?.number||`VP-ANG-${String(++S.vapeQuoteSequence).padStart(4,'0')}`,d={id,number,leadId:$('#vqCustomer').value||$('#vqLead').value,company,customerNo:$('#vqCustomerNo').value.trim(),contact:$('#vqContact').value.trim(),email:$('#vqEmail').value.trim(),vatId:$('#vqVatId').value.trim(),date:$('#vqDate').value,items,note:$('#vqNote').value.trim(),status:old?.status||'Entwurf',...t};const idx=S.vapeQuotes.findIndex(x=>x.id===id);idx>=0?S.vapeQuotes[idx]=d:S.vapeQuotes.unshift(d);save();close('vapeQuoteDialog');if(S._quoteFromCart){S.vapeCart=[];delete S._quoteFromCart;save()}render();renderVape();toast('Vape-Angebot gespeichert')};$('#vapeQuoteForm')?.addEventListener('submit',e=>{e.preventDefault();saveVapeQuote()});$('#vapeQuoteForm button.primary')?.addEventListener('click',e=>{e.preventDefault();saveVapeQuote()});
function newVapeInvoice(productId=null,quote=null,existing=null){$('#vapeInvoiceForm').reset();$('#viId').value=existing?.id||'';$('#viCustomer').innerHTML=customerOptions(existing?.leadId||quote?.leadId||'');$('#viCustomer').value=existing?.leadId||quote?.leadId||'';$('#viDate').value=existing?.date||today();$('#viDue').value=existing?.due||today();$('#viCompany').value=existing?.company||quote?.company||'';$('#viCustomerNo').value=existing?.customerNo||quote?.customerNo||'';$('#viContact').value=existing?.contact||quote?.contact||'';$('#viEmail').value=existing?.email||quote?.email||'';$('#viVatId').value=existing?.vatId||quote?.vatId||'';$('#viNote').value=existing?.note||'Zahlungsziel gemäß Vereinbarung.';$('#vapeInvoiceItems').innerHTML='';(existing?.items||quote?.items||[]).forEach(i=>newVapeLine($('#vapeInvoiceItems'),i));if(!existing?.items?.length&&!quote&&!productId)newVapeLine($('#vapeInvoiceItems'),{});if(productId)newVapeLine($('#vapeInvoiceItems'),{productId,qty:1,price:vapePrice(S.vapeProducts.find(p=>p.id===productId))});renderVapeTotals();open('vapeInvoiceDialog')}
$('#viCustomer')?.addEventListener('change',()=>fillVapeCustomer('#viCustomer','#viCompany','#viContact','#viEmail','#viVatId','#viCustomerNo'));$('#addVapeInvoiceItem')?.addEventListener('click',()=>{newVapeLine($('#vapeInvoiceItems'));renderVapeTotals()});$('#vapeInvoiceForm')?.addEventListener('submit',e=>{e.preventDefault();const items=getVapeItems($('#vapeInvoiceItems')),t=totals(items);if(!items.length)return toast('Mindestens einen Artikel mit VK auswählen');const id=$('#viId').value||uid(),old=S.vapeInvoices.find(x=>x.id===id),number=old?.number||`VP-RE-${String(++S.vapeInvoiceSequence).padStart(4,'0')}`,d={id,number,leadId:$('#viCustomer').value,company:$('#viCompany').value.trim(),customerNo:$('#viCustomerNo').value.trim(),contact:$('#viContact').value.trim(),email:$('#viEmail').value.trim(),vatId:$('#viVatId').value.trim(),date:$('#viDate').value,due:$('#viDue').value,items,note:$('#viNote').value.trim(),status:old?.status||'Offen',...t};const idx=S.vapeInvoices.findIndex(x=>x.id===id);idx>=0?S.vapeInvoices[idx]=d:S.vapeInvoices.unshift(d);save();close('vapeInvoiceDialog');render();renderVape();toast('Vape-Rechnung gespeichert')});
function printVapeDoc(doc,type){const rows=doc.items.map(i=>`<tr><td>${esc(i.description)}${i.variant?`<br><small>${esc(i.variant)}</small>`:''}</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.qty*i.price)}</td></tr>`).join('');const title=type==='invoice'?'Rechnung':'Angebot';const html=`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${title} ${esc(doc.number)}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#111}h1{margin:0 0 4px}table{width:100%;border-collapse:collapse;margin-top:30px}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}th:nth-child(n+2),td:nth-child(n+2){text-align:right}.totals{margin:30px 0 0 auto;width:280px}.totals div{display:flex;justify-content:space-between;padding:5px}.brand{font-weight:800;font-size:22px;margin-bottom:30px}.muted{color:#666}.foot{margin-top:60px;border-top:1px solid #ddd;padding-top:12px;font-size:12px;color:#555}@media print{button{display:none}}</style></head><body><div class="brand">neXaro Solutions</div><h1>${title}</h1><div class="muted">${esc(doc.number)} · ${esc(doc.date||'')}</div><h3>${esc(doc.company)}</h3><div>${esc(doc.contact||'')}</div><div>${esc(doc.email||'')}</div><table><thead><tr><th>Artikel</th><th>Menge</th><th>Einzelpreis</th><th>Gesamt</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Netto</span><b>${money(doc.net)}</b></div><div><span>MwSt. 19 %</span><b>${money(doc.vat)}</b></div><div><span>Brutto</span><b>${money(doc.gross)}</b></div></div><p>${esc(doc.note||'')}</p><div class="foot">neXaro Solutions · Kirschstraße 1A · 15757 Halbe · Kontakt@nexaro-solutions.de · www.nexaro-solutions.de · USt-IdNr. DE367084019</div><script>window.print()<\/script></body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close()}
const oldAct=act;act=function(a){if(a==='new-vape-quote')return newVapeQuote();if(a==='vape-cart-quote')return openVapeCartQuote();if(a==='new-vape-invoice')return newVapeInvoice();return oldAct(a)};
$('#vapeProductList')?.addEventListener('click',e=>{const c=e.target.closest('[data-vape-cart]');if(c&&!c.disabled)return addToVapeCart(c.dataset.vapeCart);const q=e.target.closest('[data-vape-add]');if(q&&!q.disabled)return newVapeQuote(q.dataset.vapeAdd)});
$('#vapeCart')?.addEventListener('click',e=>{const p=e.target.closest('[data-cart-plus]')?.dataset.cartPlus;if(p)return updateVapeCart(p,1);const m=e.target.closest('[data-cart-minus]')?.dataset.cartMinus;if(m)return updateVapeCart(m,-1);if(e.target.closest('[data-cart-clear]'))return clearVapeCart()});
$('#vapeQuoteList')?.addEventListener('click',e=>{let q=e.target.closest('[data-vq-edit]');if(q)return newVapeQuote(null,null,S.vapeQuotes.find(x=>x.id===q.dataset.vqEdit));q=e.target.closest('[data-vq-print]');if(q)return printVapeDoc(S.vapeQuotes.find(x=>x.id===q.dataset.vqPrint),'quote');q=e.target.closest('[data-vq-invoice]');if(q)return newVapeInvoice(null,S.vapeQuotes.find(x=>x.id===q.dataset.vqInvoice))});
$('#vapeInvoiceList')?.addEventListener('click',e=>{let q=e.target.closest('[data-vi-edit]');if(q)return newVapeInvoice(null,null,S.vapeInvoices.find(x=>x.id===q.dataset.viEdit));q=e.target.closest('[data-vi-print]');if(q)return printVapeDoc(S.vapeInvoices.find(x=>x.id===q.dataset.viPrint),'invoice')});
$('#vapeMarkup')?.addEventListener('input',e=>setVapeMarkup(e.target.value));$('#importDealerCsv')?.addEventListener('change',e=>importDealerCSV(e.target.files[0]));$('#importL3')?.addEventListener('change',e=>importPrivateL3(e.target.files[0]));
const oldRender=render;render=function(){oldRender();if($('#vape')?.classList.contains('active'))renderVape()};renderVape();
